"""Conservative numerical error estimates from executed independent controls.
These are estimates, not rigorous mathematical bounds or stand-alone physics certification.
"""
from pathlib import Path
import argparse,json,numpy as np
def main():
 ap=argparse.ArgumentParser();ap.add_argument('point',type=Path);ap.add_argument('source',type=Path);ap.add_argument('output',type=Path);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();p=json.loads(a.point.read_text());s=json.loads(a.source.read_text());o=json.loads(a.output.read_text());hr=json.loads((a.point.parent/'HARD_REFERENCE.json').read_text());out={};reserve=float(1e-6*max(1.,np.log(p['Q2']/2.)/np.log(2.3/2.)))
 for t in ['smooth','Dterm_added']:
  c=p['comparisons'][t];r=p['results'];pair=c['weak10_strong10'];terms={'candidate_representation':2*np.abs(c['weak8_weak10']['CFF_difference']),'reference_representation':2*np.abs(c['strong8_strong10']['CFF_difference']),'candidate_reference_discrepancy':np.abs(pair['CFF_difference']),'kernel_quadrature':2*sum(np.abs(s['comparisons'][l][t]['CFF_difference']) for l in ['weak10','strong10']),'output_quadrature':2*sum(np.abs(o['comparisons'][l][t]['CFF_difference']) for l in ['weak10','strong10']),'hard_quadrature':2*sum(np.array(r[l][t]['hard_96_192_component_change']) for l in ['weak10','strong10']),'ordered_time':2*sum(np.maximum(r[l][t]['ordered_tight_CFF_change'],r[l][t]['independent_RK4_CFF_change']) for l in ['weak10','strong10']),'independent_hard':2*sum(np.abs(hr['checks'][l][t][-1]['component_difference'])+np.array(hr['checks'][l][t][-1]['reference_quad_error_estimate']) for l in ['weak10','strong10']),'source_arithmetic_allowance':np.full(2,reserve)};total=sum(terms.values());limits=np.array(pair['CFF_component_threshold']);f={}
  for ch in ['Sigma','T_rescaled','Hg']:
   parts={'candidate_reference_discrepancy':pair['field_relative_L2'][ch],'candidate_representation':2*c['weak8_weak10']['field_relative_L2'][ch],'reference_representation':2*c['strong8_strong10']['field_relative_L2'][ch],'kernel_quadrature':2*sum(s['comparisons'][l][t]['field_relative_L2'][ch] for l in ['weak10','strong10']),'output_quadrature':2*sum(o['comparisons'][l][t]['field_relative_L2'][ch] for l in ['weak10','strong10']),'time_and_arithmetic_allowance':reserve};f[ch]={'terms':parts,'estimated_total':sum(parts.values()),'threshold':1e-3,'pass':sum(parts.values())<=1e-3}
  out[t]={'candidate_CFF':r['weak10'][t]['CFF'],'reference_CFF':hr['checks']['strong10'][t][-1]['reference'],'CFF_terms':{k:v.tolist() for k,v in terms.items()},'CFF_estimated_total':total.tolist(),'CFF_threshold':limits.tolist(),'CFF_component_pass':(total<=limits).tolist(),'fields':f,'representation_changes_decrease':{'weak':(np.abs(c['weak8_weak10']['CFF_difference'])<np.abs(c['weak6_weak8']['CFF_difference'])).tolist(),'strong':(np.abs(c['strong8_strong10']['CFF_difference'])<np.abs(c['strong6_strong8']['CFF_difference'])).tolist()}}
 result={'xi':p['xi'],'Q2':p['Q2'],'fixtures':out,'numerical_budget_pass':all(all(v['CFF_component_pass']) and all(q['pass'] for q in v['fields'].values()) for v in out.values()),'independent_hard_has_warnings':any(v[-1]['warnings'] for channels in hr['checks'].values() for v in channels.values()),'meaning':'Estimated numerical budget; requires separate source physics controls and independence review. No thresholds relaxed.','allowance_basis':'1e-6 times max(1,log(Q2/2)/log(2.3/2)) absolute CFF and relative field reserve for source arithmetic/local finite parts, above observed MP precision/strict-local controls and analytic-action discrepancies propagated over pilot. Quadrature changes measured separately. Not a rigorous bound.','independence':'Weak Galerkin and strong collocation share point source; separate mpmath source transcriptions, full-support adaptive/analytic actions, published spin2/charge identities, hard contour, ordered RK4 and derivative controls are required.'};a.out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
